// pages/UserProfile.tsx
import React, { useEffect, useRef, useState } from 'react';
import { useAuth } from '../contexts/AuthContext';
import { apiService, CensorshipResponse } from '../services/api';
import { usePermissions } from '../hooks/usePermissions';
import './UserProfile.css';

const UserProfile: React.FC = () => {
  const { user } = useAuth();
  const { hasPermission } = usePermissions();
  const [minioInfo, setMinioInfo] = useState<any>(null);
  const [loading, setLoading] = useState(true);
  const [userFiles, setUserFiles] = useState<any[]>([]);
  const [activeTab, setActiveTab] = useState<'account' | 'files'>('account');

  // Кнопки вместо видимого "upload input"
  const previewFileInputRef = useRef<HTMLInputElement>(null);
  const censorFileInputRef = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);
  const [censoring, setCensoring] = useState(false);
  const [actionError, setActionError] = useState<string | null>(null);

  // По умолчанию используем "pixelate" (если на проекте иначе — замените id метода)
  const selectedMethod = 'pixelate';
  const censorshipParams: Record<string, any> = { pixel_size: 15, blur_strength: 31 };

  const canUpload = hasPermission('files.upload');
  const canUseCensor = hasPermission('censor.use');

  useEffect(() => {
    const loadUserData = async () => {
      if (user) {
        try {
          console.log('🔄 [Profile] Loading user data...');

          // Загружаем информацию о MinIO (но не блокируемся на ошибке)
          try {
            const info = await apiService.getUserMinioInfo();
            console.log('📦 [Profile] MinIO Info:', info);
            setMinioInfo(info);
          } catch (minioError: any) {
            console.warn('⚠️ [Profile] Could not load MinIO info:', minioError);
            setMinioInfo({
              username: user.username,
              files_bucket: 'unknown',
              user_folder: 'unknown',
              storage_used: '0 B',
              provider: 'MinIO',
              error: minioError.message
            });
          }

          // Загружаем файлы основным методом
          console.log('📁 [Profile] Запрашиваю файлы пользователя...');

          let files = await apiService.getUserFiles();
          console.log('📁 [Profile] Main method files:', files);

          // Если основной метод вернул пустой массив, пробуем альтернативный
          if (files.length === 0) {
            try {
              files = await apiService.getUserFilesAlternative();
              console.log('📁 [Profile] Alternative method files:', files);
            } catch (altError) {
              console.error('❌ [Profile] Alternative method failed:', altError);
            }
          }

          setUserFiles(files);
        } catch (error: any) {
          console.error('❌ [Profile] Error loading user data:', error);
        } finally {
          setLoading(false);
        }
      }
    };

    loadUserData();
  }, [user]);

  const handleRefreshFiles = async () => {
    setLoading(true);

    try {
      let files = await apiService.getUserFiles();

      if (files.length === 0) {
        files = await apiService.getUserFilesAlternative();
      }

      setUserFiles(files);
    } catch (error: any) {
      console.error('❌ Error refreshing files:', error);
    } finally {
      setLoading(false);
    }
  };

  const refreshHistoryImages = async () => {
    try {
      let files = await apiService.getUserFiles();
      if (files.length === 0) {
        files = await apiService.getUserFilesAlternative();
      }
      setUserFiles(files);
    } catch (e) {
      console.error('❌ [Profile] refreshHistoryImages failed:', e);
    }
  };

  const handlePreviewUpload = async (rawFiles: FileList | null) => {
    if (!rawFiles || rawFiles.length === 0) return;
    setActionError(null);
    setUploading(true);
    try {
      if (!user) throw new Error('Для загрузки нужно войти в систему');
      if (!canUpload) throw new Error('Нет прав на загрузку файлов');

      await apiService.uploadFiles(rawFiles);
      await refreshHistoryImages();
    } catch (e: any) {
      setActionError(e?.message || 'Ошибка загрузки');
    } finally {
      setUploading(false);
      if (previewFileInputRef.current) previewFileInputRef.current.value = '';
    }
  };

  const handleApplyCensor = async (rawFile: File | null) => {
    if (!rawFile) return;
    setActionError(null);
    setCensoring(true);
    try {
      if (!user) throw new Error('Для цензуры нужно войти в систему');
      if (!canUseCensor) throw new Error('Нет прав на использование цензурирования');

      const resp: CensorshipResponse = await apiService.censorImage(
        rawFile,
        selectedMethod,
        censorshipParams
      );
      if (!resp?.success) {
        throw new Error(resp?.message || 'Ошибка при цензурировании');
      }
      await refreshHistoryImages();
    } catch (e: any) {
      setActionError(e?.message || 'Ошибка при цензурировании');
    } finally {
      setCensoring(false);
      if (censorFileInputRef.current) censorFileInputRef.current.value = '';
    }
  };

  const formatFileSize = (bytes: number): string => {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };

  const formatDate = (dateString: string): string => {
    const date = new Date(dateString);
    return date.toLocaleDateString('ru-RU', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const handleDownload = async (url: string, filename: string) => {
    try {
      await apiService.downloadFile(url, filename);
    } catch (error) {
      console.error('Error downloading file:', error);
      alert('Ошибка при скачивании файла');
    }
  };

  const handleDelete = async (file: any) => {
    if (!file.object_name) {
      alert('Не удалось определить имя файла для удаления');
      return;
    }

    const confirmed = window.confirm(
      `Вы уверены, что хотите удалить файл "${file.name}"?\n\nЭто действие нельзя отменить.`
    );

    if (!confirmed) {
      return;
    }

    try {
      setLoading(true);
      await apiService.deleteFile(file.object_name);

      // Удаляем файл из списка
      setUserFiles(prevFiles => 
        prevFiles.filter(f => f.object_name !== file.object_name)
      );

      alert('Файл успешно удален');
    } catch (error: any) {
      console.error('Error deleting file:', error);
      alert(`Ошибка при удалении файла: ${error.message || 'Неизвестная ошибка'}`);
    } finally {
      setLoading(false);
    }
  };


  // История изображений (только картинки из MinIO)
  const imageFiles = userFiles.filter((file) => {
    const name = file.name || '';
    const url = file.url || '';
    const type = file.type || '';

    const isImageByType = typeof type === 'string' && type.startsWith('image/');
    const isImageByName = typeof name === 'string' && name.match(/\.(jpg|jpeg|png|gif|bmp|webp)$/i);
    const isImageByUrl = typeof url === 'string' && url.match(/\.(jpg|jpeg|png|gif|bmp|webp)$/i);

    return isImageByType || isImageByName || isImageByUrl;
  });

  if (!user) {
    return (
      <div className="profile-container">
        <div className="profile-card">
          <h2>⚠️ Доступ запрещен</h2>
          <p>Для просмотра профиля необходимо <a href="/login">войти в систему</a></p>
        </div>
      </div>
    );
  }

  if (loading) {
    return (
      <div className="profile-container">
        <div className="loading-spinner">
          <div className="spinner"></div>
          <p>Загрузка профиля...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="user-profile">
      <div className="profile-header">
        <h1>Профиль</h1>

      </div>


      <div className="profile-tabs">
        <button 
          className={`tab-button ${activeTab === 'account' ? 'active' : ''}`}
          onClick={() => setActiveTab('account')}
        >
          Информация аккаунта
        </button>
        <button 
          className={`tab-button ${activeTab === 'files' ? 'active' : ''}`}
          onClick={() => setActiveTab('files')}
        >
          История изображений ({imageFiles.length})
        </button>
      </div>

      {activeTab === 'account' ? (
        <div className="profile-grid">
          <div className="profile-card">
            <h2>Информация аккаунта</h2>
            <div className="info-grid">
              <div className="info-item">
                <span className="info-label">Имя пользователя:</span>
                <span className="info-value">{user.username}</span>
              </div>

              {user.email && (
                <div className="info-item">
                  <span className="info-label">Email:</span>
                  <span className="info-value">{user.email}</span>
                </div>
              )}

              {user.created_at && (
                <div className="info-item">
                  <span className="info-label">Дата регистрации:</span>
                  <span className="info-value">{formatDate(user.created_at)}</span>
                </div>
              )}



              {minioInfo && (
                <>
                  <div className="info-item">
                    <span className="info-label">Хранилище:</span>
                    <span className="info-value storage-badge">{minioInfo.provider || 'MinIO'}</span>
                  </div>

                  {minioInfo.user_folder && !minioInfo.error ? (
                    <div className="info-item">
                      <span className="info-label">Папка в MinIO:</span>
                      <span className="info-value code">{minioInfo.user_folder}</span>
                    </div>
                  ) : minioInfo.error ? (
                    <div className="info-item error">
                      <span className="info-label">Статус MinIO:</span>
                      <span className="info-value error-text" title={minioInfo.error}>
                        ⚠️ Ошибка аутентификации
                      </span>
                    </div>
                  ) : null}

                  {minioInfo.files_bucket && !minioInfo.error && (
                    <div className="info-item">
                      <span className="info-label">Бакет:</span>
                      <span className="info-value">{minioInfo.files_bucket}</span>
                    </div>
                  )}

                  {minioInfo.storage_used && !minioInfo.error && (
                    <div className="info-item">
                      <span className="info-label">Использовано:</span>
                      <span className="info-value">{minioInfo.storage_used}</span>
                    </div>
                  )}
                </>
              )}
            </div>
          </div>

          <div className="profile-card">
            <h2>Системная информация</h2>
            <div className="info-grid">
              <div className="info-item">
                <span className="info-label">Система цензурирования:</span>
                <span className="info-value">AI Face Detection</span>
              </div>

              <div className="info-item">
                <span className="info-label">Методы цензурирования:</span>
                <span className="info-value">Пикселизация</span>
              </div>

              <div className="info-item">
                <span className="info-label">Поддерживаемые форматы:</span>
                <span className="info-value">JPG, PNG</span>
              </div>

              <div className="info-item">
                <span className="info-label">Максимальный размер файла:</span>
                <span className="info-value">10 MB</span>
              </div>
            </div>
          </div>
        </div>
      ) : (
        <div className="files-section">
          <div className="files-header">
            <div className="header-title">
              <h2>История изображений</h2>
              <span className="files-count">{imageFiles.length} изображений</span>
            </div>
            <div className="header-actions">
              <button 
                onClick={handleRefreshFiles}
                className="refresh-button"
                disabled={loading}
              >
                {loading ? '🔄 Обновление...' : '🔄 Обновить файлы'}
              </button>

              {/* Предварительный просмотр = загрузка через кнопку */}
              <button
                type="button"
                className="profile-action-button profile-action-button--preview"
                onClick={() => previewFileInputRef.current?.click()}
                disabled={loading || uploading || !user || !canUpload}
                title={!canUpload ? 'Нет прав на загрузку файлов' : ''}
              >
                {uploading ? 'Загрузка...' : '👁️ Предварительный просмотр'}
              </button>

              {/* Применить цензуру = выбор файла и отправка на /censor */}
              <button
                type="button"
                className="profile-action-button profile-action-button--censor"
                onClick={() => censorFileInputRef.current?.click()}
                disabled={loading || censoring || !user || !canUseCensor}
                title={!canUseCensor ? 'Нет прав на использование цензурирования' : ''}
              >
                {censoring ? 'Обработка...' : '🛡️ Применить цензуру'}
              </button>

              <input
                ref={previewFileInputRef}
                type="file"
                multiple
                accept="image/*"
                style={{ display: 'none' }}
                onChange={(e) => handlePreviewUpload(e.target.files)}
              />
              <input
                ref={censorFileInputRef}
                type="file"
                accept="image/*"
                style={{ display: 'none' }}
                onChange={(e) => handleApplyCensor(e.target.files?.[0] || null)}
              />
            </div>
          </div>

          {actionError && (
            <div className="profile-action-error" role="alert">
              {actionError}
            </div>
          )}

          {imageFiles.length === 0 ? (
            <div className="empty-files">
              <div className="empty-icon">📭</div>
              <h3>Изображения не найдены</h3>
              <p>У вас пока нет загруженных изображений в системе</p>
              <div className="empty-actions">
                <button
                  type="button"
                  onClick={() => previewFileInputRef.current?.click()}
                  className="upload-link"
                  disabled={!user || uploading || !canUpload}
                >
                  🖼️ Загрузить изображения (Предпросмотр)
                </button>
                <button 
                  onClick={() => setUserFiles([
                    {
                      name: 'demo-image.jpg',
                      url: 'https://via.placeholder.com/400x300/667eea/ffffff?text=Demo+Image',
                      size: 153600,
                      last_modified: new Date().toISOString(),
                      type: 'image/jpeg',
                      object_name: 'demo-bucket/demo-image.jpg'
                    }
                  ])}
                  className="demo-button"
                >
                  🧪 Показать демо
                </button>
              </div>
            </div>
          ) : (
            <>
              {imageFiles.some(file => file.url && file.url.includes('placeholder.com')) && (
                <div className="demo-warning">
                  ⚠️ Отображаются демо-данные. Реальные изображения из MinIO не загружены.
                  Проверьте консоль браузера для отладки.
                </div>
              )}

              <div className="files-grid">
                {imageFiles.map((file, index) => (
                  <div key={index} className="file-card">
                    <div className="file-preview">
                      {file.url && file.url.match(/\.(jpg|jpeg|png|gif|bmp|webp)$/i) ? (
                        <img 
                          src={file.url} 
                          alt={file.name} 
                          className="file-image"
                          onError={(e) => {
                            (e.target as HTMLImageElement).style.display = 'none';
                            const parent = e.currentTarget.parentElement;
                            if (parent) {
                              const fallback = document.createElement('div');
                              fallback.className = 'file-icon';
                              fallback.textContent = '📄';
                              parent.appendChild(fallback);
                            }
                          }}
                          loading="lazy"
                        />
                      ) : (
                        <div className="file-icon">
                          {file.name?.match(/\.(pdf)$/i) ? '📄' : 
                           file.name?.match(/\.(doc|docx)$/i) ? '📝' : 
                           file.name?.match(/\.(xls|xlsx)$/i) ? '📊' : 
                           '📁'}
                        </div>
                      )}
                    </div>

                    <div className="file-info">
                      <div className="file-name" title={file.name}>
                        {file.name || 'Без названия'}
                      </div>

                      <div className="file-details">
                        {file.size !== undefined && (
                          <span className="file-size">📦 {formatFileSize(file.size)}</span>
                        )}

                        {file.last_modified && (
                          <span className="file-date">📅 {formatDate(file.last_modified)}</span>
                        )}


                      </div>


                    </div>

                    <div className="file-actions">
                      <button 
                        onClick={() => handleDownload(file.url, file.name)}
                        className="action-button download"
                        title="Скачать"
                      >
                        ⬇️
                      </button>

                      {file.url && (
                        <button 
                          onClick={() => {
                            navigator.clipboard.writeText(file.url);
                            alert('Ссылка скопирована в буфер обмена');
                          }}
                          className="action-button copy"
                          title="Копировать ссылку"
                        >
                          📋
                        </button>
                      )}

                      <button 
                        onClick={() => handleDelete(file)}
                        className="action-button delete"
                        title="Удалить файл"
                        disabled={loading || !file.object_name}
                      >
                        🗑️
                      </button>
                    </div>
                  </div>
                ))}
              </div>
            </>
          )}

          {minioInfo && !minioInfo.error && (
            <div className="storage-info">
              <h3>Информация о хранилище</h3>
              <div className="storage-details">
                <div className="storage-item">
                  <span className="storage-label">Провайдер:</span>
                  <span className="storage-value">{minioInfo.provider || 'MinIO'}</span>
                </div>

                {minioInfo.files_bucket && (
                  <div className="storage-item">
                    <span className="storage-label">Бакет:</span>
                    <span className="storage-value">{minioInfo.files_bucket}</span>
                  </div>
                )}

                {minioInfo.user_folder && (
                  <div className="storage-item">
                    <span className="storage-label">Папка пользователя:</span>
                    <span className="storage-value code">{minioInfo.user_folder}</span>
                  </div>
                )}

                <div className="storage-item">
                  <span className="storage-label">Всего файлов:</span>
                  <span className="storage-value">{userFiles.length}</span>
                </div>

                {minioInfo.storage_used && (
                  <div className="storage-item">
                    <span className="storage-label">Использовано:</span>
                    <span className="storage-value">{minioInfo.storage_used}</span>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default UserProfile;
